"""Check Lark Sheet chart quality, placement, and numeric source-data issues.

The single required argument is a spreadsheet URL or spreadsheet token. By
default every worksheet is checked; pass --worksheet-id to restrict the check
to one worksheet reference_id.

Numeric source checks sample at most 50 data points per series and request at
most 2000 source cells per chart across the style and typed-value reads,
including headers and gaps between series.
Sampled zero/constant values do not establish a whole-series issue.

Exit codes:
  0: check completed and no issue was found
  1: the check could not be completed (CLI/read/response error)
  2: check completed and at least one chart-quality issue was found
"""

from __future__ import annotations

import argparse
import json
import re
from typing import Any, Dict, Tuple

from lark_sheet_read_cli import (
    LarkCliError,
    emit_error,
    envelope_data,
    resolve_target_sheets,
    run_sheets,
    sheet_identifier,
    sheet_title,
)
from lark_chart_size_rules import MAX_ASPECT_RATIO, MAX_CHART_WIDTH, minimum_chart_size

ACTION = "chart_quality_check"
DEFAULT_COLUMN_WIDTH = 105.0
DEFAULT_ROW_HEIGHT = 27.0
MAX_CELL_READ_SIZE = 2_000
MAX_SOURCE_SAMPLE_POINTS = 50


# 类型别名是运行期求值的，__future__ annotations 豁免不了它们；
# 内置泛型下标要 3.9，CI 的解释器是 3.7，只能走 typing 里的等价物。
CellBounds = Tuple[int, int, int, int]
CellCache = Dict[Tuple[str, str, str, bool], Dict[str, Any]]
SeriesProfile = Dict[str, Any]


def _parse_a1_bounds(cell_range: str) -> CellBounds:
    value = str(cell_range).rsplit("!", 1)[-1].replace("$", "")
    match = re.fullmatch(r"([A-Za-z]+)(\d+)(?::([A-Za-z]+)(\d+))?", value)
    if not match:
        raise ValueError(f"Invalid A1 range: {cell_range!r}")
    start_column = column_to_index(match.group(1))
    start_row = int(match.group(2))
    end_column = column_to_index(match.group(3) or match.group(1))
    end_row = int(match.group(4) or match.group(2))
    if end_row < start_row or end_column < start_column:
        raise ValueError(f"Invalid A1 range: {cell_range!r}")
    return start_row, end_row, start_column, end_column


def _format_a1_bounds(bounds: CellBounds) -> str:
    start_row, end_row, start_column, end_column = bounds
    return (
        f"{index_to_column(start_column)}{start_row}:"
        f"{index_to_column(end_column)}{end_row}"
    )


def _bounds_area(bounds: CellBounds) -> int:
    start_row, end_row, start_column, end_column = bounds
    return (end_row - start_row + 1) * (end_column - start_column + 1)


def _merge_bounds(first: CellBounds, second: CellBounds) -> CellBounds:
    return (
        min(first[0], second[0]),
        max(first[1], second[1]),
        min(first[2], second[2]),
        max(first[3], second[3]),
    )


def _cluster_cell_reads(
    items: list[tuple[dict[str, Any], CellBounds]],
) -> list[dict[str, Any]]:
    clusters: list[dict[str, Any]] = []
    for rectangle, bounds in sorted(items, key=lambda item: (item[1][0], item[1][2])):
        if clusters:
            merged = _merge_bounds(clusters[-1]["bounds"], bounds)
            if _bounds_area(merged) <= MAX_CELL_READ_SIZE:
                clusters[-1]["bounds"] = merged
                clusters[-1]["members"].append((rectangle, bounds))
                continue
        clusters.append({"bounds": bounds, "members": [(rectangle, bounds)]})
    return clusters


def column_to_index(column: str) -> int:
    value = 0
    text = str(column).strip().upper()
    if not text or not text.isalpha():
        raise ValueError(f"Invalid column: {column!r}")
    for char in text:
        value = value * 26 + ord(char) - ord("A") + 1
    return value - 1


def index_to_column(index: int) -> str:
    if index < 0:
        raise ValueError(f"Invalid column index: {index}")
    chars: list[str] = []
    value = index + 1
    while value:
        value, remainder = divmod(value - 1, 26)
        chars.append(chr(ord("A") + remainder))
    return "".join(reversed(chars))


def _span_bounds(span: str, *, columns: bool) -> tuple[int, int]:
    start, separator, end = str(span).partition(":")
    end = end if separator else start
    if columns:
        return column_to_index(start), column_to_index(end)
    return int(start) - 1, int(end) - 1


def _size_edges(
    groups: Any,
    *,
    count: int,
    span_key: str,
    size_key: str,
    columns: bool,
    default_size: float,
) -> tuple[list[float], bool]:
    sizes: list[float | None] = [None] * count
    if isinstance(groups, list):
        for group in groups:
            if not isinstance(group, dict) or group.get(span_key) is None:
                continue
            start, end = _span_bounds(str(group[span_key]), columns=columns)
            size = float(group.get(size_key, default_size))
            for index in range(max(0, start), min(count - 1, end) + 1):
                sizes[index] = max(0.0, size)

    used_default = any(size is None for size in sizes)
    resolved = [default_size if size is None else size for size in sizes]
    edges = [0.0]
    for size in resolved:
        edges.append(edges[-1] + size)
    return edges, used_default


def build_layout(
    structure: dict[str, Any], row_count: int, column_count: int
) -> tuple[list[float], list[float], list[str]]:
    row_groups = structure.get("row_heights")
    column_groups = structure.get("col_widths", structure.get("column_widths"))
    row_edges, row_defaulted = _size_edges(
        row_groups,
        count=row_count,
        span_key="rows",
        size_key="height",
        columns=False,
        default_size=DEFAULT_ROW_HEIGHT,
    )
    column_edges, column_defaulted = _size_edges(
        column_groups,
        count=column_count,
        span_key="cols",
        size_key="width",
        columns=True,
        default_size=DEFAULT_COLUMN_WIDTH,
    )
    warnings: list[str] = []
    if row_defaulted:
        warnings.append("部分行缺少高度信息，按 27 px 估算")
    if column_defaulted:
        warnings.append("部分列缺少宽度信息，按 105 px 估算")
    return row_edges, column_edges, warnings


def _first_dict(value: Any) -> dict[str, Any] | None:
    if isinstance(value, dict):
        return value
    if isinstance(value, list):
        return next((item for item in value if isinstance(item, dict)), None)
    return None


def extract_sheet_structure(data: dict[str, Any]) -> dict[str, Any]:
    sheet = _first_dict(data.get("sheets")) or _first_dict(data.get("sheet"))
    return sheet or data


def extract_charts(data: dict[str, Any], sheet_id: str, title: str) -> list[dict[str, Any]]:
    sheets = data.get("sheets")
    if isinstance(sheets, list):
        for sheet in sheets:
            if not isinstance(sheet, dict):
                continue
            if sheet_identifier(sheet) == sheet_id or sheet_title(sheet) == title:
                charts = sheet.get("charts")
                return [chart for chart in charts if isinstance(chart, dict)] if isinstance(charts, list) else []
    charts = data.get("charts")
    return [chart for chart in charts if isinstance(chart, dict)] if isinstance(charts, list) else []


def chart_rectangle(
    chart: dict[str, Any], row_edges: list[float], column_edges: list[float]
) -> dict[str, Any]:
    details = chart.get("details") if isinstance(chart.get("details"), dict) else chart
    position = details.get("position") if isinstance(details.get("position"), dict) else {}
    offset = details.get("offset") if isinstance(details.get("offset"), dict) else {}
    size = details.get("size") if isinstance(details.get("size"), dict) else {}

    row = int(position["row"])
    column = column_to_index(str(position["col"]))
    if row < 0 or column < 0 or row >= len(row_edges) - 1 or column >= len(column_edges) - 1:
        raise ValueError(f"anchor outside sheet: {position!r}")

    width = float(size["width"])
    height = float(size["height"])
    if width <= 0 or height <= 0:
        raise ValueError(f"invalid chart size: {size!r}")

    left = column_edges[column] + float(offset.get("col_offset", 0) or 0)
    top = row_edges[row] + float(offset.get("row_offset", 0) or 0)
    return {
        "chart_id": str(chart.get("chart_id") or chart.get("id") or ""),
        "anchor_cell": f"{index_to_column(column)}{row + 1}",
        "left": left,
        "top": top,
        "right": left + width,
        "bottom": top + height,
        "width": width,
        "height": height,
    }


def intersection(first: dict[str, Any], second: dict[str, Any]) -> dict[str, float] | None:
    left = max(float(first["left"]), float(second["left"]))
    top = max(float(first["top"]), float(second["top"]))
    right = min(float(first["right"]), float(second["right"]))
    bottom = min(float(first["bottom"]), float(second["bottom"]))
    if right <= left or bottom <= top:
        return None
    return {
        "width": round(right - left, 2),
        "height": round(bottom - top, 2),
        "area": round((right - left) * (bottom - top), 2),
    }


def chart_context(rectangle: dict[str, Any]) -> dict[str, Any]:
    return {
        "chart_id": rectangle["chart_id"],
        "anchor_cell": rectangle["anchor_cell"],
        "rectangle_px": {
            "left": round(rectangle["left"], 2),
            "top": round(rectangle["top"], 2),
            "right": round(rectangle["right"], 2),
            "bottom": round(rectangle["bottom"], 2),
            "width": round(rectangle["width"], 2),
            "height": round(rectangle["height"], 2),
        },
    }


def _covered_indexes(edges: list[float], start: float, end: float) -> list[int]:
    return [
        index
        for index in range(len(edges) - 1)
        if edges[index + 1] > start and edges[index] < end
    ]


def rectangle_cell_range(
    rectangle: dict[str, Any], row_edges: list[float], column_edges: list[float]
) -> str | None:
    rows = _covered_indexes(row_edges, max(0.0, rectangle["top"]), rectangle["bottom"])
    columns = _covered_indexes(column_edges, max(0.0, rectangle["left"]), rectangle["right"])
    if not rows or not columns:
        return None
    return f"{index_to_column(columns[0])}{rows[0] + 1}:{index_to_column(columns[-1])}{rows[-1] + 1}"


def _has_content(cell: Any) -> bool:
    if not isinstance(cell, dict):
        return False
    for key in ("value", "formula", "note"):
        value = cell.get(key)
        if value not in (None, ""):
            return True
    return bool(cell.get("rich_text") or cell.get("multiple_values"))


def _iter_cells(data: dict[str, Any]):
    ranges = data.get("ranges")
    if not isinstance(ranges, list):
        return
    for result_range in ranges:
        if not isinstance(result_range, dict):
            continue
        cells = result_range.get("cells")
        rows = result_range.get("row_indices")
        columns = result_range.get("col_indices")
        if not isinstance(cells, list):
            continue
        for row_offset, row in enumerate(cells):
            if not isinstance(row, list):
                continue
            row_number = int(rows[row_offset]) if isinstance(rows, list) and row_offset < len(rows) else row_offset + 1
            for column_offset, cell in enumerate(row):
                column = columns[column_offset] if isinstance(columns, list) and column_offset < len(columns) else index_to_column(column_offset)
                yield row_number, column_to_index(str(column)), cell


def non_empty_cells(
    data: dict[str, Any], sample_limit: int, bounds: CellBounds | None = None
) -> tuple[int, list[str], bool]:
    count = 0
    samples: list[str] = []
    truncated = bool(data.get("has_more"))
    ranges = data.get("ranges")
    if not isinstance(ranges, list):
        return 0, [], truncated
    for result_range in ranges:
        if not isinstance(result_range, dict):
            continue
        truncated = truncated or bool(result_range.get("truncated"))
    for row_number, column_index, cell in _iter_cells(data):
        if bounds and not (
            bounds[0] <= row_number <= bounds[1]
            and bounds[2] <= column_index <= bounds[3]
        ):
            continue
        if not _has_content(cell):
            continue
        count += 1
        if len(samples) < sample_limit:
            samples.append(f"{index_to_column(column_index)}{row_number}")
    return count, samples, truncated


def _read_cells(
    cache: CellCache,
    locator: dict[str, str],
    *,
    sheet_id: str | None,
    sheet_name: str | None,
    cell_range: str,
    include: str,
    skip_hidden: bool = False,
    timeout: int,
) -> dict[str, Any]:
    selector = f"id:{sheet_id}" if sheet_id else f"name:{sheet_name}"
    key = (selector, cell_range, include, skip_hidden)
    if key not in cache:
        flags: dict[str, Any] = {"range": cell_range, "include": include}
        if skip_hidden:
            flags["skip-hidden"] = True
        cache[key] = envelope_data(
            run_sheets(
                "+cells-get",
                **locator,
                **({"sheet_id": sheet_id} if sheet_id else {"sheet_name": sheet_name}),
                flags=flags,
                timeout=timeout,
            )
        )
    return cache[key]


def _read_typed_table(
    cache: CellCache,
    locator: dict[str, str],
    *,
    sheet_id: str | None,
    sheet_name: str | None,
    cell_range: str,
    timeout: int,
) -> tuple[list[list[Any]], list[str], bool]:
    selector = f"id:{sheet_id}" if sheet_id else f"name:{sheet_name}"
    key = (selector, cell_range, "typed_table", False)
    if key not in cache:
        cache[key] = envelope_data(
            run_sheets(
                "+table-get",
                **locator,
                **({"sheet_id": sheet_id} if sheet_id else {"sheet_name": sheet_name}),
                flags={"range": cell_range, "no-header": True},
                timeout=timeout,
            )
        )
    data = cache[key]
    sheets = data.get("sheets")
    if not isinstance(sheets, list) or len(sheets) != 1 or not isinstance(sheets[0], dict):
        return [], [], True
    table = sheets[0]
    rows = table.get("data")
    columns = table.get("columns")
    dtypes = table.get("dtypes")
    if not isinstance(rows, list) or not isinstance(columns, list) or not isinstance(dtypes, dict):
        return [], [], True
    def value_kind(dtype: Any) -> str:
        value = str(dtype or "").lower()
        if value in {"number", "int64", "float64"}:
            return "number"
        if value in {"bool", "boolean"}:
            return "bool"
        if value.startswith("datetime"):
            return "date"
        return "string"

    types = [value_kind(dtypes.get(str(column))) for column in columns]
    truncated = bool(data.get("truncated")) or bool(table.get("truncated"))
    return rows, types, truncated


def _typed_cell(
    rows: list[list[Any]],
    column_types: list[str],
    row_offset: int,
    column_offset: int,
    visible_offsets: set[tuple[int, int]],
) -> tuple[Any, str]:
    if (
        row_offset < 0
        or row_offset >= len(rows)
        or not isinstance(rows[row_offset], list)
        or column_offset < 0
        or column_offset >= len(rows[row_offset])
    ):
        return None, ""
    value = rows[row_offset][column_offset]
    if isinstance(value, bool):
        return value, "bool"
    if isinstance(value, (int, float)):
        return value, "number"
    kind = column_types[column_offset] if column_offset < len(column_types) else ""
    if kind != "string" or not isinstance(value, str) or not _looks_numeric(value):
        return value, kind

    # table-get infers one dtype per physical column. A hidden cell or another
    # row-series can widen that dtype and stringify otherwise numeric cells.
    # Treat such cells as unknown instead of reporting a false storage issue.
    numeric_string_count = 0
    for other_row_offset, row in enumerate(rows):
        if not isinstance(row, list) or column_offset >= len(row):
            continue
        other = row[column_offset]
        if other not in (None, "") and (other_row_offset, column_offset) not in visible_offsets:
            return value, "unknown"
        if other in (None, "") or (
            isinstance(other, (int, float)) and not isinstance(other, bool)
        ):
            continue
        if isinstance(other, str) and _looks_numeric(other):
            numeric_string_count += 1
            continue
        return value, "unknown"
    return value, "string" if numeric_string_count == 1 else "ambiguous_string"


def _numeric_source_format_reason(
    value: Any,
    raw_type: str,
    number_format: Any,
) -> tuple[str, bool]:
    if not _looks_numeric(str(value or "")):
        return "", False
    if str(number_format or "").strip() == "@":
        return "numeric_value_uses_text_format", False
    if raw_type == "string":
        return "numeric_value_stored_as_text", False
    return "", raw_type in {"ambiguous_string", "unknown"}


def _chart_snapshot(chart: dict[str, Any]) -> dict[str, Any]:
    details = chart.get("details") if isinstance(chart.get("details"), dict) else chart
    snapshot = details.get("snapshot")
    return snapshot if isinstance(snapshot, dict) else {}


def _chart_type(snapshot: dict[str, Any]) -> str:
    plot_area = snapshot.get("plotArea")
    plot = plot_area.get("plot") if isinstance(plot_area, dict) else None
    return str(plot.get("type") or "").lower() if isinstance(plot, dict) else ""


def _plot(snapshot: dict[str, Any]) -> dict[str, Any]:
    plot_area = snapshot.get("plotArea")
    plot = plot_area.get("plot") if isinstance(plot_area, dict) else None
    return plot if isinstance(plot, dict) else {}


def _static_series_profiles(snapshot: dict[str, Any]) -> list[SeriesProfile]:
    data = snapshot.get("data")
    dim2 = data.get("dim2") if isinstance(data, dict) else None
    fields = dim2.get("fields") if isinstance(dim2, dict) else None
    if not isinstance(fields, list):
        return []
    profiles: list[SeriesProfile] = []
    for offset, field in enumerate(fields, start=1):
        if not isinstance(field, dict):
            continue
        values = []
        for value in field.get("parsedValues") or []:
            numeric = (
                float(value)
                if isinstance(value, (int, float)) and not isinstance(value, bool)
                else _numeric_text_value(value) if isinstance(value, str) else None
            )
            if numeric is not None:
                values.append(numeric)
        profiles.append(
            {
                "dimension_index": offset,
                "series_name": str(field.get("name") or f"Series {offset}"),
                "point_count": len(field.get("parsedValues") or []),
                "numeric_value_count": len(values),
                "unique_numeric_values": list(dict.fromkeys(values))[:2],
                "source_sheet": "",
                "source_range": "",
                "series_range": "",
            }
        )
    return profiles


def _labeled_series_indexes(
    snapshot: dict[str, Any], profiles: list[SeriesProfile]
) -> set[int]:
    plot = _plot(snapshot)
    available = {
        int(profile["dimension_index"])
        for profile in profiles
        if profile.get("dimension_index") is not None
    }
    labeled = set(available) if isinstance(plot.get("labels"), dict) else set()
    series = plot.get("series")
    if isinstance(series, list):
        labeled.update(
            int(item["index"])
            for item in series
            if isinstance(item, dict)
            and item.get("index") is not None
            and isinstance(item.get("labels"), dict)
        )
    return labeled & available


def _constant_labeled_series(
    chart: dict[str, Any], profiles: list[SeriesProfile]
) -> list[dict[str, Any]]:
    chart_id = str(chart.get("chart_id") or chart.get("id") or "")
    snapshot = _chart_snapshot(chart)
    labeled = _labeled_series_indexes(snapshot, profiles)
    return [
        {
            "chart_id": chart_id,
            "dimension_index": profile["dimension_index"],
            "series_name": profile["series_name"],
            "source_sheet": profile["source_sheet"],
            "source_range": profile["source_range"],
            "series_range": profile["series_range"],
            "reason": "constant_labeled_series",
            "data_point_count": profile["point_count"],
            "constant_value": profile["unique_numeric_values"][0],
            "suggested_fix": "remove_series_labels_or_use_one_sparse_marker",
        }
        for profile in profiles
        if int(profile.get("dimension_index", -1)) in labeled
        and profile.get("constant_check_unverifiable") is not True
        and int(profile.get("numeric_value_count", 0)) >= 2
        and len(profile.get("unique_numeric_values") or []) == 1
    ]


def _unbound_secondary_axis(chart: dict[str, Any]) -> dict[str, Any] | None:
    snapshot = _chart_snapshot(chart)
    plot_area = snapshot.get("plotArea")
    if not isinstance(plot_area, dict):
        return None
    plot = plot_area.get("plot")
    if not isinstance(plot, dict) or str(plot.get("type") or "").lower() != "combo":
        return None

    axes = plot_area.get("axes")
    has_right_axis = isinstance(axes, list) and any(
        isinstance(axis, dict)
        and str(axis.get("type") or "").lower() == "y"
        and str(axis.get("position") or axis.get("axisPosition") or "").lower() == "right"
        for axis in axes
    )
    series = plot.get("series")
    configured_series = (
        [item for item in series if isinstance(item, dict)]
        if isinstance(series, list)
        else []
    )
    if not has_right_axis or not configured_series:
        return None
    if str(plot.get("yAxisPosition") or "").lower() == "right" or any(
        str(item.get("yAxisPosition") or "").lower() == "right"
        for item in configured_series
    ):
        return None

    return {
        "chart_id": str(chart.get("chart_id") or chart.get("id") or ""),
        "reason": "secondary_axis_has_no_bound_series",
        "series_indexes": [
            int(item["index"])
            for item in configured_series
            if isinstance(item.get("index"), (int, float))
        ],
        "suggested_fix": "bind_the_intended_combo_series_to_the_right_axis",
    }


def _undersized_chart(chart: dict[str, Any]) -> dict[str, Any] | None:
    details = chart.get("details") if isinstance(chart.get("details"), dict) else chart
    snapshot = _chart_snapshot(chart)
    chart_type = _chart_type(snapshot)
    size = details.get("size")
    if not isinstance(size, dict):
        return None
    width = size.get("width")
    height = size.get("height")
    if (
        not isinstance(width, (int, float))
        or isinstance(width, bool)
        or width <= 0
        or not isinstance(height, (int, float))
        or isinstance(height, bool)
        or height <= 0
    ):
        return None
    actual = {
        "width": float(width),
        "height": float(height),
    }
    minimum = minimum_chart_size(chart_type)
    if actual["width"] >= minimum["width"] and actual["height"] >= minimum["height"]:
        return None
    return {
        "chart_id": str(chart.get("chart_id") or chart.get("id") or ""),
        "reason": "chart_below_minimum_size",
        "chart_type": chart_type,
        "actual_size": actual,
        "minimum_size": minimum,
        "suggested_fix": "run_lark_chart_size_advisor_before_resizing",
    }


def _overwide_chart(chart: dict[str, Any]) -> dict[str, Any] | None:
    details = chart.get("details") if isinstance(chart.get("details"), dict) else chart
    snapshot = _chart_snapshot(chart)
    chart_type = _chart_type(snapshot)
    size = details.get("size") if isinstance(details.get("size"), dict) else {}
    width = size.get("width")
    height = size.get("height")
    if (
        not isinstance(width, (int, float))
        or isinstance(width, bool)
        or width <= 0
        or not isinstance(height, (int, float))
        or isinstance(height, bool)
        or height <= 0
    ):
        return None
    width = float(width)
    height = float(height)
    minimum = minimum_chart_size(chart_type)
    aspect_ratio = width / height if height > 0 else 0
    width_exceeded = width > MAX_CHART_WIDTH
    aspect_ratio_exceeded = (
        width >= minimum["width"]
        and height >= minimum["height"]
        and aspect_ratio > MAX_ASPECT_RATIO
    )
    if not width_exceeded and not aspect_ratio_exceeded:
        return None
    return {
        "chart_id": str(chart.get("chart_id") or chart.get("id") or ""),
        "reason": "chart_too_wide",
        "chart_type": chart_type,
        "actual_size": {"width": width, "height": height},
        "actual_aspect_ratio": round(aspect_ratio, 2),
        "maximum_width": MAX_CHART_WIDTH,
        "maximum_aspect_ratio": MAX_ASPECT_RATIO,
        "suggested_fix": "use_size_advisor_create_flags_or_change_chart_structure",
    }


def _numeric_dimensions(snapshot: dict[str, Any]) -> list[tuple[int, str]]:
    data = snapshot.get("data")
    if not isinstance(data, dict):
        return []
    dim2 = data.get("dim2")
    series = dim2.get("series") if isinstance(dim2, dict) else None
    chart_type = _chart_type(snapshot)
    dimensions: list[tuple[int, str]] = []
    if isinstance(series, list):
        for offset, serie in enumerate(series):
            if not isinstance(serie, dict) or serie.get("index") is None:
                continue
            if str(serie.get("aggregateType") or "").lower() == "counta":
                continue
            role = str(serie.get("role") or "").lower()
            if chart_type == "bubble":
                role = role or ("x", "y", "group", "size")[min(offset, 3)]
                if role not in {"x", "y", "size"}:
                    continue
            dimensions.append((int(serie["index"]), role or "value"))

    plot_area = snapshot.get("plotArea")
    axes = plot_area.get("axes") if isinstance(plot_area, dict) else None
    continuous_x = chart_type == "scatter"
    if isinstance(axes, list):
        for axis in axes:
            if not isinstance(axis, dict) or str(axis.get("type") or "").lower() != "x":
                continue
            position = axis.get("position")
            if (
                (position is None or str(position).lower() in {"bottom", "x"})
                and str(axis.get("valueType") or "").lower() == "linear"
            ):
                continuous_x = True
                break
    dim1 = data.get("dim1")
    serie = dim1.get("serie") if isinstance(dim1, dict) else None
    if continuous_x and chart_type != "bubble" and isinstance(serie, dict) and serie.get("index") is not None:
        dimensions.append((int(serie["index"]), "x"))

    return list(dict.fromkeys(dimensions))


def _series_aggregate_type(data: dict[str, Any], dimension_index: int) -> str:
    dim2 = data.get("dim2")
    value_series = dim2.get("series") if isinstance(dim2, dict) else None
    source_series = next(
        (
            item
            for item in (value_series if isinstance(value_series, list) else [])
            if isinstance(item, dict)
            and item.get("index") is not None
            and int(item["index"]) == dimension_index
        ),
        {},
    )
    return str(source_series.get("aggregateType") or "sum").lower()


def _aggregation_can_change_constant(data: dict[str, Any], dimension_index: int) -> bool:
    dim1 = data.get("dim1")
    category_series = dim1.get("serie") if isinstance(dim1, dict) else None
    if not isinstance(category_series, dict) or category_series.get("aggregate") is False:
        return False
    return _series_aggregate_type(data, dimension_index) in {"sum", "count", "counta"}


def _parse_chart_ref(value: str, default_sheet: str) -> tuple[str, str, CellBounds]:
    raw = str(value).strip()
    sheet_name = default_sheet
    cell_range = raw
    if "!" in raw:
        sheet_name, cell_range = raw.rsplit("!", 1)
        sheet_name = sheet_name.strip()
        if len(sheet_name) >= 2 and sheet_name[0] == sheet_name[-1] == "'":
            sheet_name = sheet_name[1:-1].replace("''", "'")
    return sheet_name, cell_range.replace("$", ""), _parse_a1_bounds(cell_range)


def _looks_numeric(value: str) -> bool:
    return _numeric_text_value(value) is not None


def _numeric_text_value(value: str) -> float | None:
    text = value.strip()
    if not text:
        return None
    text = re.sub(r"^([+-]?)[\$\u00a5\uffe5\u20ac\u00a3]", r"\1", text)
    if text.endswith("%"):
        text = text[:-1]
    # Group separators must be consistent and separate groups of three digits.
    if not re.fullmatch(
        r"[+-]?(?:(?:\d+|\d{1,3}([, ])\d{3}(?:\1\d{3})*)(?:\.\d*)?|\.\d+)"
        r"(?:[eE][+-]?\d+)?",
        text,
    ):
        return None
    return float(text.replace(" ", "").replace(",", ""))


def _zero_state(value: Any) -> str:
    if value in (None, ""):
        return "empty"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return "zero" if value == 0 else "nonzero"
    if isinstance(value, str):
        numeric_value = _numeric_text_value(value)
        if numeric_value is not None:
            return "zero" if numeric_value == 0 else "nonzero"
    return "nonzero"


def _update_series_state(state: dict[str, Any], value: Any) -> None:
    state[_zero_state(value)] = True
    numeric = (
        float(value)
        if isinstance(value, (int, float)) and not isinstance(value, bool)
        else _numeric_text_value(value) if isinstance(value, str) else None
    )
    if numeric is None:
        return
    state["numeric_value_count"] += 1
    if len(state["unique_numeric_values"]) < 2:
        state["unique_numeric_values"].add(numeric)


def _cells_truncated(data: dict[str, Any]) -> bool:
    ranges = data.get("ranges")
    return bool(data.get("has_more")) or any(
        isinstance(item, dict) and item.get("truncated")
        for item in (ranges if isinstance(ranges, list) else [])
    )


def _numeric_source_issues(
    chart: dict[str, Any],
    *,
    owner_sheet_id: str,
    owner_sheet_name: str,
    cache: CellCache,
    locator: dict[str, str],
    timeout: int,
    sample_limit: int,
) -> tuple[
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, str]],
    list[SeriesProfile],
]:
    chart_id = str(chart.get("chart_id") or chart.get("id") or "")
    snapshot = _chart_snapshot(chart)
    data = snapshot.get("data")
    if not isinstance(data, dict):
        return [], [], [{"chart_id": chart_id, "reason": "chart snapshot.data is missing"}], []
    if data.get("isStaticData") is True:
        return [], [], [], _static_series_profiles(snapshot)
    dimensions = _numeric_dimensions(snapshot)
    if not dimensions:
        return [], [], [], []
    refs = data.get("refs")
    if not isinstance(refs, list) or not refs:
        return [], [], [{"chart_id": chart_id, "reason": "chart data.refs is missing"}], []

    parsed_refs: list[tuple[str, str, CellBounds]] = []
    unverifiable: list[dict[str, str]] = []
    for ref in refs:
        raw_ref = ref.get("value") if isinstance(ref, dict) else ref
        try:
            parsed_refs.append(_parse_chart_ref(str(raw_ref), owner_sheet_name))
        except (TypeError, ValueError) as exc:
            unverifiable.append({"chart_id": chart_id, "reason": str(exc)})
            return [], [], unverifiable, []

    direction = str(data.get("direction") or "column").lower()
    skip_hidden = data.get("includeHiddenOrFilter") is not True
    mapped: list[tuple[int, str, int, str, str, CellBounds]] = []
    for dimension_index, role in dimensions:
        offset = 0
        for source_sheet, source_range, bounds in parsed_refs:
            dimension_count = (
                bounds[3] - bounds[2] + 1 if direction == "column" else bounds[1] - bounds[0] + 1
            )
            if offset < dimension_index <= offset + dimension_count:
                mapped.append(
                    (
                        dimension_index,
                        role,
                        dimension_index - offset,
                        source_sheet,
                        source_range,
                        bounds,
                    )
                )
                break
            offset += dimension_count
        else:
            unverifiable.append(
                {
                    "chart_id": chart_id,
                    "reason": f"numeric dimension index {dimension_index} is outside data.refs",
                }
            )

    detached = str(data.get("headerMode") or "").lower() == "detached"
    mapped_by_ref: dict[
        tuple[str, str, CellBounds], list[tuple[int, str, int]]
    ] = {}
    for dimension_index, role, local_index, source_sheet, source_range, bounds in mapped:
        mapped_by_ref.setdefault((source_sheet, source_range, bounds), []).append(
            (dimension_index, role, local_index)
        )

    issue_groups: dict[tuple[int, str, str, str, str, str], list[str]] = {}
    issue_counts: dict[tuple[int, str, str, str, str, str], int] = {}
    degenerate_series: list[dict[str, Any]] = []
    series_profiles: list[SeriesProfile] = []
    remaining_source_cells = MAX_CELL_READ_SIZE
    remaining_dimension_spans = sum(
        max(local_index for _, _, local_index in ref_dimensions)
        - min(local_index for _, _, local_index in ref_dimensions)
        + 1
        for ref_dimensions in mapped_by_ref.values()
    )
    for (source_sheet, source_range, bounds), ref_dimensions in mapped_by_ref.items():
        dimension_start = bounds[2] if direction == "column" else bounds[0]
        selected = {
            dimension_start + local_index - 1: (dimension_index, role)
            for dimension_index, role, local_index in ref_dimensions
        }
        dimension_span = max(selected) - min(selected) + 1
        header_points = 0 if detached else 1
        # Each sampled rectangle is read twice: cells-get supplies coordinates,
        # styles, and hidden/filter semantics; table-get supplies typed values.
        cells_per_dimension = remaining_source_cells // remaining_dimension_spans
        remaining_dimension_spans -= dimension_span
        point_axis_size = (
            bounds[1] - bounds[0] + 1
            if direction == "column"
            else bounds[3] - bounds[2] + 1
        )
        if point_axis_size <= header_points:
            unverifiable.append(
                {
                    "chart_id": chart_id,
                    "reason": f"source has no data points: {source_sheet}!{source_range}",
                }
            )
            continue
        sample_points = min(MAX_SOURCE_SAMPLE_POINTS, max(0, (cells_per_dimension - header_points) // 2))
        if sample_points == 0:
            unverifiable.append({
                "chart_id": chart_id,
                "reason": f"source sampling 2000-cell budget cannot cover {source_sheet}!{source_range}",
            })
            continue
        point_count = sample_points + header_points
        if direction == "column":
            checked_bounds = (
                bounds[0],
                min(bounds[1], bounds[0] + point_count - 1),
                min(selected),
                max(selected),
            )
        else:
            checked_bounds = (
                min(selected),
                max(selected),
                bounds[2],
                min(bounds[3], bounds[2] + point_count - 1),
            )
        typed_bounds = (
            (checked_bounds[0] + header_points, checked_bounds[1], checked_bounds[2], checked_bounds[3])
            if direction == "column"
            else (checked_bounds[0], checked_bounds[1], checked_bounds[2] + header_points, checked_bounds[3])
        )
        remaining_source_cells -= _bounds_area(checked_bounds) + _bounds_area(typed_bounds)
        checked_range = _format_a1_bounds(checked_bounds)
        same_sheet = source_sheet == owner_sheet_name
        cells_data = _read_cells(
            cache,
            locator,
            sheet_id=owner_sheet_id if same_sheet else None,
            sheet_name=None if same_sheet else source_sheet,
            cell_range=checked_range,
            include="value,style",
            skip_hidden=skip_hidden,
            timeout=timeout,
        )
        cells_truncated = _cells_truncated(cells_data)
        typed_rows, typed_columns, table_truncated = _read_typed_table(
            cache,
            locator,
            sheet_id=owner_sheet_id if same_sheet else None,
            sheet_name=None if same_sheet else source_sheet,
            cell_range=_format_a1_bounds(typed_bounds),
            timeout=timeout,
        )
        if cells_truncated:
            unverifiable.append(
                {"chart_id": chart_id, "reason": f"cells-get truncated for {source_sheet}!{checked_range}"}
            )
        if table_truncated:
            unverifiable.append(
                {
                    "chart_id": chart_id,
                    "reason": (
                        "table-get truncated or returned invalid typed data for "
                        f"{source_sheet}!{_format_a1_bounds(typed_bounds)}"
                    ),
                }
            )
        truncated = cells_truncated or table_truncated
        states = {
            coordinate: {
                "zero": False,
                "empty": False,
                "nonzero": False,
                "sample_point_count": 0,
                "numeric_value_count": 0,
                "unique_numeric_values": set(),
            }
            for coordinate in selected
        }
        type_unverifiable_dimensions: set[int] = set()
        visible_offsets = {
            (row_number - typed_bounds[0], column_index - typed_bounds[2])
            for row_number, column_index, _ in _iter_cells(cells_data)
            if typed_bounds[0] <= row_number <= typed_bounds[1]
            and typed_bounds[2] <= column_index <= typed_bounds[3]
        }
        for row_number, column_index, cell in _iter_cells(cells_data):
            coordinate = column_index if direction == "column" else row_number
            dimension = selected.get(coordinate)
            if dimension is None:
                continue
            if not detached and (
                (direction == "column" and row_number == bounds[0])
                or (direction != "column" and column_index == bounds[2])
            ):
                continue
            states[coordinate]["sample_point_count"] += 1
            row_offset = row_number - typed_bounds[0]
            column_offset = column_index - typed_bounds[2]
            value, raw_type = _typed_cell(
                typed_rows,
                typed_columns,
                row_offset,
                column_offset,
                visible_offsets,
            )
            _update_series_state(states[coordinate], value)
            number_format = (
                cell.get("cell_styles", {}).get("number_format")
                if isinstance(cell, dict) and isinstance(cell.get("cell_styles"), dict)
                else None
            )
            reason, type_unverifiable = _numeric_source_format_reason(
                value,
                raw_type,
                number_format,
            )
            if type_unverifiable:
                type_unverifiable_dimensions.add(dimension[0])
            if not reason:
                continue
            dimension_index, role = dimension
            key = (
                dimension_index,
                role,
                source_sheet,
                source_range,
                checked_range,
                reason,
            )
            issue_counts[key] = issue_counts.get(key, 0) + 1
            samples = issue_groups.setdefault(key, [])
            if len(samples) < sample_limit:
                samples.append(f"{index_to_column(column_index)}{row_number}")

        if truncated:
            continue
        for dimension_index in sorted(type_unverifiable_dimensions):
            unverifiable.append(
                {
                    "chart_id": chart_id,
                    "reason": (
                        "numeric storage type cannot be attributed to individual cells after "
                        f"typed column coercion for {source_sheet}!{checked_range}, "
                        f"dimension {dimension_index}"
                    ),
                }
            )
        zero_candidates = {
            coordinate
            for coordinate, state in states.items()
            if not state["nonzero"]
            and _series_aggregate_type(data, selected[coordinate][0]) != "count"
        }
        data_start = bounds[0] + (0 if detached else 1)
        data_column = bounds[2] + (0 if detached else 1)
        dim2 = data.get("dim2")
        value_series = dim2.get("series") if isinstance(dim2, dict) else None
        for coordinate, state in states.items():
            dimension_index, role = selected[coordinate]
            if direction == "column":
                point_total = max(0, bounds[1] - data_start + 1)
                series_range = (
                    f"{index_to_column(coordinate)}{data_start}:"
                    f"{index_to_column(coordinate)}{bounds[1]}"
                    if point_total
                    else ""
                )
            else:
                point_total = max(0, bounds[3] - data_column + 1)
                series_range = (
                    f"{index_to_column(data_column)}{coordinate}:"
                    f"{index_to_column(bounds[3])}{coordinate}"
                    if point_total
                    else ""
                )
            source_series = next(
                (
                    item
                    for item in (value_series if isinstance(value_series, list) else [])
                    if isinstance(item, dict)
                    and item.get("index") is not None
                    and int(item["index"]) == dimension_index
                ),
                {},
            )
            profile = {
                "dimension_index": dimension_index,
                "series_name": str(
                    source_series.get("name")
                    or source_series.get("nameRef")
                    or f"Series {dimension_index}"
                ),
                "point_count": point_total,
                "sample_point_count": state["sample_point_count"],
                "checked_range": checked_range,
                "sampled": (
                    checked_bounds[1] < bounds[1]
                    if direction == "column"
                    else checked_bounds[3] < bounds[3]
                ),
                "numeric_value_count": state["numeric_value_count"],
                "unique_numeric_values": list(state["unique_numeric_values"]),
                "source_sheet": source_sheet,
                "source_range": source_range,
                "series_range": series_range,
            }
            aggregate_type = _series_aggregate_type(data, dimension_index)
            if aggregate_type == "count":
                profile["constant_check_unverifiable"] = True
            constant_labeled = (
                aggregate_type != "count"
                and state["numeric_value_count"] >= 2
                and len(state["unique_numeric_values"]) == 1
                and dimension_index
                in _labeled_series_indexes(snapshot, [{"dimension_index": dimension_index}])
            )
            if profile["sampled"]:
                profile["constant_check_unverifiable"] = True
                if coordinate in zero_candidates or constant_labeled:
                    unverifiable.append({
                        "chart_id": chart_id,
                        "reason": (
                            "zero/constant-series check is unverifiable outside sampled source "
                            f"{source_sheet}!{checked_range} for dimension {dimension_index}"
                        ),
                    })
            elif constant_labeled and _aggregation_can_change_constant(data, dimension_index):
                profile["constant_check_unverifiable"] = True
                unverifiable.append(
                    {
                        "chart_id": chart_id,
                        "reason": (
                            "constant-series check is unverifiable after category "
                            f"aggregation for dimension {dimension_index}"
                        ),
                    }
                )
            series_profiles.append(profile)
            if coordinate not in zero_candidates or profile["sampled"]:
                continue
            degenerate_series.append(
                {
                    "chart_id": chart_id,
                    "dimension_index": dimension_index,
                    "role": role,
                    "source_sheet": source_sheet,
                    "source_range": source_range,
                    "series_range": series_range,
                    "reason": (
                        "numeric_series_all_zero_or_empty"
                        if states[coordinate]["zero"]
                        else "numeric_series_all_empty"
                    ),
                    "data_point_count": point_total,
                }
            )

    issues = [
        {
            "chart_id": chart_id,
            "dimension_index": key[0],
            "role": key[1],
            "source_sheet": key[2],
            "source_range": key[3],
            "checked_range": key[4],
            "reason": key[5],
            "suggested_fix": (
                "set_numeric_number_format"
                if key[5] == "numeric_value_uses_text_format"
                else "rewrite_as_number_and_set_numeric_number_format"
            ),
            "affected_sample_cell_count": issue_counts[key],
            "sample_cells": samples,
        }
        for key, samples in issue_groups.items()
    ]
    return issues, degenerate_series, unverifiable, series_profiles


def _locator(target: str) -> dict[str, str]:
    return {"url": target} if target.startswith(("http://", "https://")) else {"spreadsheet_token": target}


def _sheet_counts(sheet: dict[str, Any]) -> tuple[int, int]:
    row_count = int(sheet.get("row_count") or sheet.get("rowCount") or 0)
    column_count = int(sheet.get("column_count") or sheet.get("columnCount") or 0)
    if row_count <= 0 or column_count <= 0:
        raise LarkCliError(f"Missing row_count/column_count for sheet {sheet_title(sheet)!r}")
    return row_count, column_count


def check_sheet(
    locator: dict[str, str],
    sheet: dict[str, Any],
    *,
    timeout: int,
    sample_limit: int,
    cell_cache: CellCache | None = None,
) -> dict[str, Any]:
    cell_cache = cell_cache if cell_cache is not None else {}
    sheet_id = sheet_identifier(sheet)
    title = sheet_title(sheet)
    if not sheet_id:
        raise LarkCliError(f"Missing sheet_id for sheet {title!r}")

    chart_data = envelope_data(
        run_sheets("+chart-list", **locator, sheet_id=sheet_id, timeout=timeout)
    )
    charts = extract_charts(chart_data, sheet_id, title)
    unverifiable: list[dict[str, str]] = []
    expected_chart_count = sheet.get("chart_count")
    if expected_chart_count is not None and int(expected_chart_count) != len(charts):
        unverifiable.append(
            {
                "chart_id": "",
                "reason": (
                    f"chart-list returned {len(charts)} charts, "
                    f"but workbook-info reported {int(expected_chart_count)}"
                ),
            }
        )
    if not charts:
        return {
            "sheet_id": sheet_id,
            "sheet_name": title,
            "chart_count": 0,
            "sheet_size_px": None,
            "chart_overlaps": [],
            "cell_content_overlaps": [],
            "numeric_source_format_issues": [],
            "numeric_source_samples": [],
            "degenerate_numeric_series": [],
            "constant_labeled_series": [],
            "unbound_secondary_axes": [],
            "undersized_charts": [],
            "overwide_charts": [],
            "out_of_visible_range": [],
            "unverifiable_charts": unverifiable,
            "issue_count": 0,
            "unverifiable_count": len(unverifiable),
            "warnings": [],
        }

    row_count, column_count = _sheet_counts(sheet)
    structure_data = envelope_data(
        run_sheets(
            "+sheet-info",
            **locator,
            sheet_id=sheet_id,
            flags={"include": "row_heights,col_widths"},
            timeout=timeout,
        )
    )
    row_edges, column_edges, warnings = build_layout(
        extract_sheet_structure(structure_data), row_count, column_count
    )

    rectangles: list[dict[str, Any]] = []
    for chart in charts:
        chart_id = str(chart.get("chart_id") or chart.get("id") or "")
        if not chart_id:
            unverifiable.append({"chart_id": "", "reason": "chart is missing chart_id"})
            continue
        try:
            rectangles.append(chart_rectangle(chart, row_edges, column_edges))
        except (KeyError, TypeError, ValueError) as exc:
            unverifiable.append({"chart_id": chart_id, "reason": str(exc)})

    overlaps: list[dict[str, Any]] = []
    for index, first in enumerate(rectangles):
        for second in rectangles[index + 1 :]:
            overlap = intersection(first, second)
            if overlap:
                overlaps.append(
                    {
                        "chart_ids": [first["chart_id"], second["chart_id"]],
                        "charts": [chart_context(first), chart_context(second)],
                        "intersection": overlap,
                    }
                )

    sheet_width = column_edges[-1]
    sheet_height = row_edges[-1]
    out_of_bounds: list[dict[str, Any]] = []
    content_overlaps: list[dict[str, Any]] = []
    covered_items: list[tuple[dict[str, Any], CellBounds]] = []
    for rectangle in rectangles:
        overflow = {
            "left": round(max(0.0, -rectangle["left"]), 2),
            "top": round(max(0.0, -rectangle["top"]), 2),
            "right": round(max(0.0, rectangle["right"] - sheet_width), 2),
            "bottom": round(max(0.0, rectangle["bottom"] - sheet_height), 2),
        }
        if any(overflow.values()):
            out_of_bounds.append({**chart_context(rectangle), "overflow_px": overflow})

        covered_range = rectangle_cell_range(rectangle, row_edges, column_edges)
        if not covered_range:
            continue
        covered_items.append((rectangle, _parse_a1_bounds(covered_range)))

    for cluster in _cluster_cell_reads(covered_items):
        read_range = _format_a1_bounds(cluster["bounds"])
        cells_data = _read_cells(
            cell_cache,
            locator,
            sheet_id=sheet_id,
            sheet_name=None,
            cell_range=read_range,
            include="value,formula,comment",
            timeout=timeout,
        )
        for rectangle, bounds in cluster["members"]:
            covered_range = _format_a1_bounds(bounds)
            count, samples, truncated = non_empty_cells(cells_data, sample_limit, bounds)
            if truncated:
                unverifiable.append(
                    {
                        "chart_id": rectangle["chart_id"],
                        "reason": f"cells-get truncated for {read_range}",
                    }
                )
            if count:
                content_overlaps.append(
                    {
                        **chart_context(rectangle),
                        "covered_range": covered_range,
                        "non_empty_cell_count": count,
                        "sample_cells": samples,
                    }
                )

    numeric_source_issues: list[dict[str, Any]] = []
    numeric_source_samples: list[dict[str, Any]] = []
    degenerate_numeric_series: list[dict[str, Any]] = []
    constant_series_issues: list[dict[str, Any]] = []
    unbound_secondary_axes: list[dict[str, Any]] = []
    undersized_charts: list[dict[str, Any]] = []
    overwide_charts: list[dict[str, Any]] = []
    for chart in charts:
        issues, degenerate, source_unverifiable, profiles = _numeric_source_issues(
            chart,
            owner_sheet_id=sheet_id,
            owner_sheet_name=title,
            cache=cell_cache,
            locator=locator,
            timeout=timeout,
            sample_limit=sample_limit,
        )
        numeric_source_issues.extend(issues)
        numeric_source_samples.extend(
            {"chart_id": str(chart.get("chart_id") or chart.get("id") or ""), **profile}
            for profile in profiles
            if "checked_range" in profile
        )
        degenerate_numeric_series.extend(degenerate)
        unverifiable.extend(source_unverifiable)
        constant_series_issues.extend(_constant_labeled_series(chart, profiles))
        unbound_secondary_axis = _unbound_secondary_axis(chart)
        if unbound_secondary_axis:
            unbound_secondary_axes.append(unbound_secondary_axis)
        undersized = _undersized_chart(chart)
        if undersized:
            undersized_charts.append(undersized)
        overwide = _overwide_chart(chart)
        if overwide:
            overwide_charts.append(overwide)

    issue_count = (
        len(overlaps)
        + len(out_of_bounds)
        + len(content_overlaps)
        + len(numeric_source_issues)
        + len(degenerate_numeric_series)
        + len(constant_series_issues)
        + len(unbound_secondary_axes)
        + len(undersized_charts)
        + len(overwide_charts)
    )
    return {
        "sheet_id": sheet_id,
        "sheet_name": title,
        "chart_count": len(charts),
        "sheet_size_px": {"width": round(sheet_width, 2), "height": round(sheet_height, 2)},
        "chart_overlaps": overlaps,
        "cell_content_overlaps": content_overlaps,
        "numeric_source_format_issues": numeric_source_issues,
        "numeric_source_samples": numeric_source_samples,
        "degenerate_numeric_series": degenerate_numeric_series,
        "constant_labeled_series": constant_series_issues,
        "unbound_secondary_axes": unbound_secondary_axes,
        "undersized_charts": undersized_charts,
        "overwide_charts": overwide_charts,
        "out_of_visible_range": out_of_bounds,
        "unverifiable_charts": unverifiable,
        "issue_count": issue_count,
        "unverifiable_count": len(unverifiable),
        "warnings": warnings,
    }


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Check chart overlap, covered cell content, worksheet boundary overflow, "
            "minimum size, excessive width, constant labeled series, numeric source-cell "
            "formats, all-zero/empty numeric series, and unbound combo-chart secondary axes."
        )
    )
    parser.add_argument("sheet_id", help="Spreadsheet URL or spreadsheet token")
    parser.add_argument("--worksheet-id", help="Only check this worksheet reference_id")
    parser.add_argument("--timeout", type=int, default=60)
    parser.add_argument("--sample-limit", type=int, default=10)
    return parser.parse_args()


def success_envelope(results: list[dict[str, Any]]) -> dict[str, Any]:
    issue_count = sum(result["issue_count"] for result in results)
    unverifiable_count = sum(result["unverifiable_count"] for result in results)
    warnings = [
        f"{result['sheet_name'] or result['sheet_id']}: {warning}"
        for result in results
        for warning in result["warnings"]
    ]
    return {
        "ok": True,
        "engine": "lark",
        "action": ACTION,
        "data": {
            "passed": issue_count == 0 and unverifiable_count == 0,
            "scope_note": (
                "out_of_visible_range checks worksheet drawable bounds, not a device-specific browser viewport; "
                "numeric source checks sample at most the first 50 data points of each chart value dimension "
                "for formats, all-zero/empty, and constant-value checks; zero/constant results are conclusive "
                "only when that sample covers the complete series, otherwise they are marked unverifiable"
            ),
            "summary": {
                "worksheet_count": len(results),
                "chart_count": sum(result["chart_count"] for result in results),
                "issue_count": issue_count,
                "unverifiable_count": unverifiable_count,
            },
            "sheets": results,
        },
        "warnings": warnings,
    }


def report_exit_code(report: dict[str, Any]) -> int:
    if report["data"]["passed"]:
        return 0
    if report["data"]["summary"]["issue_count"] > 0:
        return 2
    return 1


def main() -> None:
    args = parse_args()
    locator = _locator(args.sheet_id)
    cell_cache: CellCache = {}
    try:
        workbook_data = envelope_data(
            run_sheets("+workbook-info", **locator, timeout=args.timeout)
        )
        sheets = resolve_target_sheets(workbook_data, sheet_id=args.worksheet_id)
        if not args.worksheet_id:
            sheets = [sheet for sheet in sheets if not bool(sheet.get("is_hidden"))]
        if not sheets:
            raise LarkCliError("No visible worksheet matched")
        results = [
            check_sheet(
                locator,
                sheet,
                timeout=args.timeout,
                sample_limit=args.sample_limit,
                cell_cache=cell_cache,
            )
            for sheet in sheets
        ]
    except (LarkCliError, KeyError, TypeError, ValueError) as exc:
        emit_error(ACTION, str(exc))
        raise SystemExit(1) from exc

    report = success_envelope(results)
    print(json.dumps(report, ensure_ascii=False, indent=2))
    exit_code = report_exit_code(report)
    if exit_code:
        raise SystemExit(exit_code)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# Copyright (c) 2026 Lark Technologies Pte. Ltd.
# SPDX-License-Identifier: MIT
"""Recommend a Lark Sheet chart size before creating the chart object."""

from __future__ import annotations

import argparse
import json
import re
from typing import Any

from lark_chart_size_rules import SUPPORTED_CHART_TYPES, recommend_chart_size
from lark_sheet_read_cli import (
    LarkCliError,
    emit_error,
    emit_success,
    envelope_data,
    extract_sheets,
    run_sheets,
    sheet_identifier,
    sheet_title,
)

ACTION = "chart_size_advisor"


def _locator(target: str) -> dict[str, str]:
    return {"url": target} if target.startswith(("http://", "https://")) else {"spreadsheet_token": target}


def _split_range_refs(value: str) -> list[str]:
    refs: list[str] = []
    start = 0
    quoted = False
    index = 0
    while index < len(value):
        char = value[index]
        if char == "'":
            if quoted and index + 1 < len(value) and value[index + 1] == "'":
                index += 2
                continue
            quoted = not quoted
        elif char == "," and not quoted:
            ref = value[start:index].strip()
            if ref:
                refs.append(ref)
            start = index + 1
        index += 1
    tail = value[start:].strip()
    if tail:
        refs.append(tail)
    if not refs or quoted:
        raise ValueError(f"Invalid data range: {value!r}")
    return refs


def _parse_ref(value: str) -> tuple[str | None, str]:
    raw = value.strip()
    sheet_name = None
    cell_range = raw
    if "!" in raw:
        sheet_name, cell_range = raw.rsplit("!", 1)
        sheet_name = sheet_name.strip()
        if len(sheet_name) >= 2 and sheet_name[0] == sheet_name[-1] == "'":
            sheet_name = sheet_name[1:-1].replace("''", "'")
    cell_range = cell_range.replace("$", "")
    if not re.fullmatch(r"[A-Za-z]+\d+:[A-Za-z]+\d+", cell_range):
        raise ValueError(f"Invalid A1 range: {value!r}")
    return sheet_name, cell_range


def _cell_value(cell: Any) -> Any:
    if not isinstance(cell, dict):
        return None
    return cell.get("value", cell.get("raw_value"))


def _matrix(data: dict[str, Any]) -> list[list[Any]]:
    ranges = data.get("ranges")
    if not isinstance(ranges, list) or not ranges:
        return []
    result = ranges[0]
    cells = result.get("cells") if isinstance(result, dict) else None
    if not isinstance(cells, list):
        return []
    return [
        [_cell_value(cell) for cell in row]
        for row in cells
        if isinstance(row, list)
    ]


def _is_network_timeout(exc: LarkCliError) -> bool:
    text = str(exc).strip()
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        payload = None
    if isinstance(payload, dict):
        error = payload.get("error")
        if isinstance(error, dict) and str(error.get("subtype") or "").lower() == "timeout":
            return True
    lowered = text.lower()
    return "server time out" in lowered or "timed out" in lowered


def _run_read(
    shortcut: str,
    *,
    stage: str,
    timeout: int,
    **kwargs: Any,
) -> dict[str, Any]:
    retried = False
    while True:
        try:
            return run_sheets(shortcut, timeout=timeout, **kwargs)
        except LarkCliError as exc:
            if not retried and _is_network_timeout(exc):
                retried = True
                continue
            suffix = " after one retry" if retried else ""
            raise LarkCliError(f"{stage} failed{suffix}: {exc}", cmd=exc.cmd) from exc


def _sheet_selector(
    sheets: list[dict[str, Any]],
    *,
    explicit_name: str | None,
    worksheet_id: str | None,
    worksheet_name: str | None,
) -> dict[str, str]:
    if explicit_name:
        return {"sheet_name": explicit_name}
    if worksheet_id:
        return {"sheet_id": worksheet_id}
    if worksheet_name:
        return {"sheet_name": worksheet_name}
    if len(sheets) != 1:
        raise LarkCliError("Unqualified data ranges require --worksheet-id or --worksheet-name")
    sheet_id = sheet_identifier(sheets[0])
    if sheet_id:
        return {"sheet_id": sheet_id}
    return {"sheet_name": sheet_title(sheets[0])}


def _needs_workbook_metadata(
    ranges: list[str | None],
    *,
    worksheet_id: str | None,
    worksheet_name: str | None,
) -> bool:
    if worksheet_id or worksheet_name:
        return False
    return any(
        _parse_ref(ref)[0] is None
        for value in ranges
        if value
        for ref in _split_range_refs(value)
    )


def _read_ranges(
    locator: dict[str, str],
    sheets: list[dict[str, Any]],
    value: str,
    *,
    worksheet_id: str | None,
    worksheet_name: str | None,
    timeout: int,
    stage_prefix: str = "data range",
) -> list[list[list[Any]]]:
    matrices: list[list[list[Any]]] = []
    for ref in _split_range_refs(value):
        explicit_name, cell_range = _parse_ref(ref)
        selector = _sheet_selector(
            sheets,
            explicit_name=explicit_name,
            worksheet_id=worksheet_id,
            worksheet_name=worksheet_name,
        )
        data = envelope_data(
            _run_read(
                "+cells-get",
                stage=f"{stage_prefix} {ref}",
                **locator,
                **selector,
                flags={"range": cell_range, "include": "value"},
                timeout=timeout,
            )
        )
        matrix = _matrix(data)
        if not matrix:
            raise LarkCliError(f"No cells returned for {ref}")
        matrices.append(matrix)
    return matrices


def _combine(matrices: list[list[list[Any]]], direction: str) -> list[list[Any]]:
    if direction == "column":
        row_count = len(matrices[0])
        if any(len(matrix) != row_count for matrix in matrices):
            raise ValueError("Column-direction ranges must contain the same number of rows")
        return [sum((matrix[row] for matrix in matrices), []) for row in range(row_count)]
    column_count = max((len(row) for row in matrices[0]), default=0)
    if any(max((len(row) for row in matrix), default=0) != column_count for matrix in matrices):
        raise ValueError("Row-direction ranges must contain the same number of columns")
    return sum(matrices, [])


def _parse_indexes(value: str | None, *, dimension_count: int, dim1_index: int) -> list[int]:
    indexes = (
        [int(item.strip()) for item in value.split(",") if item.strip()]
        if value
        else [index for index in range(1, dimension_count + 1) if index != dim1_index]
    )
    if not indexes or any(index < 1 or index > dimension_count for index in indexes):
        raise ValueError("--dim2-indexes contains an out-of-range dimension index")
    if dim1_index in indexes:
        raise ValueError("--dim1-index cannot also appear in --dim2-indexes")
    return indexes


def _numeric(value: Any) -> float | None:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    if isinstance(value, str):
        text = value.strip().replace(",", "")
        if text.endswith("%"):
            text = text[:-1]
        try:
            return float(text)
        except ValueError:
            return None
    return None


def profile_matrix(
    matrix: list[list[Any]],
    *,
    direction: str,
    dim1_index: int,
    dim2_indexes: str | None,
    detached_headers: list[Any] | None = None,
) -> dict[str, Any]:
    if not matrix:
        raise ValueError("Data range is empty")
    dimension_count = max((len(row) for row in matrix), default=0) if direction == "column" else len(matrix)
    if dim1_index < 1 or dim1_index > dimension_count:
        raise ValueError("--dim1-index is outside the data range")
    selected = _parse_indexes(
        dim2_indexes,
        dimension_count=dimension_count,
        dim1_index=dim1_index,
    )
    detached = detached_headers is not None
    if direction == "column":
        data_rows = matrix if detached else matrix[1:]
        categories = [row[dim1_index - 1] if len(row) >= dim1_index else None for row in data_rows]
        headers = detached_headers or matrix[0]
        series_names = [str(headers[index - 1]) if len(headers) >= index else f"Series {index}" for index in selected]
        first_values = [row[selected[0] - 1] if len(row) >= selected[0] else None for row in data_rows]
    else:
        category_row = matrix[dim1_index - 1]
        categories = category_row if detached else category_row[1:]
        headers = detached_headers or [row[0] if row else None for row in matrix]
        series_names = [str(headers[index - 1]) if len(headers) >= index else f"Series {index}" for index in selected]
        first_row = matrix[selected[0] - 1]
        first_values = first_row if detached else first_row[1:]
    nonempty_categories = [value for value in categories if value not in (None, "")]
    return {
        "categories": nonempty_categories,
        "series_names": series_names,
        # 海象运算符要 3.8，CI 的解释器是 3.7：先映射再滤空，语义等价。
        "values": [n for n in (_numeric(v) for v in first_values) if n is not None],
        "dim2_indexes": selected,
    }


def _header_values(matrices: list[list[list[Any]]], direction: str) -> list[Any]:
    matrix = _combine(matrices, direction)
    if direction == "column":
        if len(matrix) != 1:
            raise ValueError("Column-direction --header-range must contain one row")
        return matrix[0]
    if any(len(row) != 1 for row in matrix):
        raise ValueError("Row-direction --header-range must contain one column")
    return [row[0] for row in matrix]


def _boolean_argument(value: str) -> bool:
    normalized = str(value).strip().lower()
    if normalized == "true":
        return True
    if normalized == "false":
        return False
    raise argparse.ArgumentTypeError("expected true or false")


def _comma_separated_values(value: str) -> list[str]:
    values = [item.strip() for item in str(value).split(",")]
    if not values or any(not item for item in values):
        raise argparse.ArgumentTypeError("expected a comma-separated list")
    return values


def _series_y_axes_argument(value: str) -> list[str]:
    values = _comma_separated_values(value)
    invalid = [item for item in values if item not in {"left", "right"}]
    if invalid:
        raise argparse.ArgumentTypeError(
            f"unsupported series Y axis {invalid[0]!r}; expected left or right"
        )
    return values


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Recommend chart width and height before +chart-create-basic")
    parser.add_argument("target", help="Spreadsheet URL or spreadsheet token")
    worksheet = parser.add_mutually_exclusive_group()
    worksheet.add_argument("--worksheet-id")
    worksheet.add_argument("--worksheet-name")
    parser.add_argument("--chart-type", choices=sorted(SUPPORTED_CHART_TYPES), required=True)
    parser.add_argument("--data-range", required=True)
    parser.add_argument("--header-range")
    parser.add_argument("--data-direction", choices=("column", "row"), default="column")
    parser.add_argument("--dim1-index", type=int, default=1)
    parser.add_argument("--dim2-indexes")
    parser.add_argument("--series-types", type=_comma_separated_values)
    parser.add_argument("--series-y-axes", type=_series_y_axes_argument)
    parser.add_argument("--data-labels", default="none")
    parser.add_argument("--aggregate-categories", type=_boolean_argument, default=True)
    parser.add_argument("--legend-position", default="bottom")
    parser.add_argument("--title", default="")
    parser.add_argument("--timeout", type=int, default=60)
    return parser.parse_args(argv)


def main() -> None:
    args = parse_args()
    locator = _locator(args.target)
    try:
        sheets: list[dict[str, Any]] = []
        if _needs_workbook_metadata(
            [args.data_range, args.header_range],
            worksheet_id=args.worksheet_id,
            worksheet_name=args.worksheet_name,
        ):
            workbook = envelope_data(
                _run_read(
                    "+workbook-info",
                    stage="workbook metadata",
                    **locator,
                    timeout=args.timeout,
                )
            )
            sheets = extract_sheets(workbook)
        matrices = _read_ranges(
            locator,
            sheets,
            args.data_range,
            worksheet_id=args.worksheet_id,
            worksheet_name=args.worksheet_name,
            timeout=args.timeout,
        )
        headers = None
        if args.header_range:
            header_matrices = _read_ranges(
                locator,
                sheets,
                args.header_range,
                worksheet_id=args.worksheet_id,
                worksheet_name=args.worksheet_name,
                timeout=args.timeout,
                stage_prefix="header range",
            )
            headers = _header_values(header_matrices, args.data_direction)
        profile = profile_matrix(
            _combine(matrices, args.data_direction),
            direction=args.data_direction,
            dim1_index=args.dim1_index,
            dim2_indexes=args.dim2_indexes,
            detached_headers=headers,
        )
        result = recommend_chart_size(
            chart_type=args.chart_type,
            categories=profile["categories"],
            series_names=profile["series_names"],
            data_labels=args.data_labels,
            legend_position=args.legend_position,
            title=args.title,
            values=profile["values"],
            aggregate_categories=args.aggregate_categories,
            series_types=args.series_types,
            series_y_axes=args.series_y_axes,
        )
        result["data_profile"] = {
            "dim2_indexes": profile["dim2_indexes"],
            **result.pop("evidence"),
        }
    except (LarkCliError, KeyError, TypeError, ValueError) as exc:
        emit_error(ACTION, str(exc))
        raise SystemExit(1) from exc
    emit_success(ACTION, result)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# Copyright (c) 2026 Lark Technologies Pte. Ltd.
# SPDX-License-Identifier: MIT
"""Detect occupied subtable regions in a Lark sheet."""

from __future__ import annotations

import argparse
import csv
import io
import re
from collections import deque
from dataclasses import dataclass
from typing import Any

from lark_sheet_range import RangeBounds, col_to_index, format_range, index_to_col, parse_range, range_union
from lark_sheet_read_cli import (
    LarkCliError,
    add_spreadsheet_args,
    emit_error,
    emit_success,
    envelope_data,
    resolve_target_sheets,
    run_sheets,
    sheet_identifier,
    sheet_locator,
    sheet_title,
)

ACTION = "detect_subtables"
ROW_PREFIX_RE = re.compile(r"^\[row=(\d+)\]\s?(.*)$")
MAX_EXTERNAL_MERGE_ANCHOR_CHECKS = 10


def _inside_quoted_field(lines: list[str]) -> bool:
    """True when the accumulated record has an unterminated quoted field.

    RFC 4180 escapes a literal quote by doubling it, so both halves of a `""`
    pair count and parity still tracks whether a field is left open. A record
    that is still open must swallow the next physical line verbatim — even one
    that looks like a `[row=N]` prefix, because inside quotes that text is
    ordinary cell content, not a new record.
    """
    return sum(line.count('"') for line in lines) % 2 == 1


@dataclass
class CsvGrid:
    row_numbers: list[int]
    col_letters: list[str]
    values: list[list[str]]
    row_numbers_inferred: bool = False


@dataclass
class Component:
    bounds: RangeBounds
    occupied_count: int


def parse_annotated_csv(
    text: str,
    col_indices: list[str] | None = None,
    row_indices: list[int] | None = None,
    source_range: str | None = None,
) -> CsvGrid:
    row_numbers: list[int] = []
    values: list[list[str]] = []
    max_cols = 0
    lines = (text or "").splitlines()
    row_numbers_inferred = False
    has_authoritative_rows = isinstance(row_indices, list) and len(row_indices) > 0

    first_meaningful = next((line for line in lines if line.strip()), "")
    if ROW_PREFIX_RE.match(first_meaningful):
        records = []
        current_lines: list[str] | None = None
        current_row_number: int | None = None
        for line in lines:
            match = ROW_PREFIX_RE.match(line)
            if match and current_lines is not None and _inside_quoted_field(current_lines):
                # Prefix-looking text inside an open quoted field is content.
                current_lines.append(line)
                continue
            if match:
                if current_lines is not None and current_row_number is not None:
                    records.append("\n".join(current_lines))
                    row_numbers.append(current_row_number)
                current_row_number = int(match.group(1))
                current_lines = [match.group(2)]
            elif current_lines is not None:
                current_lines.append(line)
        if current_lines is not None and current_row_number is not None:
            records.append("\n".join(current_lines))
            row_numbers.append(current_row_number)

        # Cross-check against the row numbers the server itself reported.
        # _inside_quoted_field decides whether a "[row=N]" line starts a new
        # record or is content inside an open quoted field; when the payload's
        # quoting is malformed (a lone unescaped quote in a cell), that call
        # goes the wrong way and every following line is swallowed into the
        # previous cell — the rows simply vanish, and everything downstream
        # (data_range, last data row, column profiles) is quietly computed from
        # a short grid. row_indices is authoritative and already in hand, so
        # refuse rather than profile a grid that does not match it.
        if has_authoritative_rows and row_numbers != [int(r) for r in row_indices]:
            raise ValueError(
                "annotated_csv did not parse into the rows the server reported "
                f"(parsed {len(row_numbers)} rows {row_numbers[:5]}…, expected "
                f"{len(row_indices)} rows {list(row_indices)[:5]}…) — most likely "
                "an unbalanced quote in a cell. Re-read a narrower --range, or use "
                "+cells-get for this region instead of the CSV path."
            )

        for record in records:
            parsed = next(csv.reader([record]))
            values.append(parsed)
            max_cols = max(max_cols, len(parsed))
    else:
        reader = csv.reader(io.StringIO(text or ""))
        fallback_start = 1
        if source_range:
            fallback_start = parse_range(
                source_range,
                max_row=1_048_576,
                max_col=18_278,
            ).start_row
        for offset, row in enumerate(reader):
            row_num = None
            if has_authoritative_rows and offset < len(row_indices):
                try:
                    row_num = int(row_indices[offset])
                except (TypeError, ValueError):
                    # Non-numeric row index: leave row_num as None so the
                    # inferred fallback numbering below takes over.
                    pass
            if row_num is None:
                row_numbers_inferred = True
            row_numbers.append(row_num if row_num is not None else fallback_start + offset)
            values.append(row)
            max_cols = max(max_cols, len(row))

    if col_indices:
        col_letters = [str(col) for col in col_indices[:max_cols]]
        while len(col_letters) < max_cols:
            next_col = col_to_index(col_letters[-1]) + 1 if col_letters else len(col_letters) + 1
            col_letters.append(index_to_col(next_col))
    else:
        col_letters = [index_to_col(i) for i in range(1, max_cols + 1)]

    for row in values:
        row.extend([""] * (len(col_letters) - len(row)))
    inferred = bool(values) and not ROW_PREFIX_RE.match(first_meaningful) and (
        row_numbers_inferred or not has_authoritative_rows
    )
    return CsvGrid(
        row_numbers=row_numbers,
        col_letters=col_letters,
        values=values,
        row_numbers_inferred=inferred,
    )


def _merged_ranges(layout: dict[str, Any]) -> list[str]:
    merges = layout.get("merged_cells") or layout.get("merges") or []
    result = []
    for item in merges:
        if isinstance(item, str):
            result.append(item)
        elif isinstance(item, dict):
            value = item.get("range") or item.get("a1_range") or item.get("range_ref")
            if isinstance(value, str):
                result.append(value)
    return result


def _scan_bounds(grid: CsvGrid) -> RangeBounds | None:
    col_numbers = [col_to_index(col) for col in grid.col_letters]
    if grid.row_numbers and grid.col_letters:
        return RangeBounds(
            min(grid.row_numbers),
            min(col_numbers),
            max(grid.row_numbers),
            max(col_numbers),
        )
    return None


def _external_merge_anchors(grid: CsvGrid, layout: dict[str, Any]) -> dict[str, str]:
    scan_bounds = _scan_bounds(grid)
    if scan_bounds is None:
        return {}
    result = {}
    for merge_ref in _merged_ranges(layout):
        try:
            bounds = parse_range(merge_ref)
        except ValueError:
            continue
        intersects = not (
            bounds.end_row < scan_bounds.start_row
            or bounds.start_row > scan_bounds.end_row
            or bounds.end_col < scan_bounds.start_col
            or bounds.start_col > scan_bounds.end_col
        )
        anchor_in_scan = (
            scan_bounds.start_row <= bounds.start_row <= scan_bounds.end_row
            and scan_bounds.start_col <= bounds.start_col <= scan_bounds.end_col
        )
        if intersects and not anchor_in_scan:
            result[merge_ref] = format_range(
                bounds.start_row, bounds.start_col, bounds.start_row, bounds.start_col
            )
    return result


def _has_value(grid: CsvGrid) -> bool:
    return any(value.strip() for row in grid.values for value in row)


def build_occupancy(
    grid: CsvGrid,
    layout: dict[str, Any],
    *,
    confirmed_external_merges: set[str] | None = None,
) -> set[tuple[int, int]]:
    col_numbers = [col_to_index(col) for col in grid.col_letters]
    occupied: set[tuple[int, int]] = set()
    for row_idx, row_num in enumerate(grid.row_numbers):
        for col_idx, value in enumerate(grid.values[row_idx]):
            if value.strip():
                occupied.add((row_num, col_numbers[col_idx]))

    scan_bounds = _scan_bounds(grid)

    for merge_ref in _merged_ranges(layout):
        try:
            bounds = parse_range(merge_ref)
        except ValueError:
            continue
        if scan_bounds is None:
            continue
        anchor_in_scan = (
            scan_bounds.start_row <= bounds.start_row <= scan_bounds.end_row
            and scan_bounds.start_col <= bounds.start_col <= scan_bounds.end_col
        )
        if anchor_in_scan and (bounds.start_row, bounds.start_col) not in occupied:
            continue
        if not anchor_in_scan and merge_ref not in (confirmed_external_merges or set()):
            continue
        sr = max(bounds.start_row, scan_bounds.start_row)
        er = min(bounds.end_row, scan_bounds.end_row)
        sc = max(bounds.start_col, scan_bounds.start_col)
        ec = min(bounds.end_col, scan_bounds.end_col)
        if sr > er or sc > ec:
            continue
        for row in range(sr, er + 1):
            for col in range(sc, ec + 1):
                occupied.add((row, col))
    return occupied


def _raw_components(
    occupied: set[tuple[int, int]],
    *,
    adjacent_rows: dict[int, set[int]] | None = None,
    adjacent_cols: dict[int, set[int]] | None = None,
) -> list[Component]:
    remaining = set(occupied)
    components = []
    while remaining:
        start = remaining.pop()
        queue = deque([start])
        cells = [start]
        while queue:
            row, col = queue.popleft()
            vertical_rows = adjacent_rows.get(row, set()) if adjacent_rows else {row - 1, row + 1}
            neighbors = [(neighbor_row, col) for neighbor_row in vertical_rows]
            # Columns get the same treatment as rows: with --skip-hidden the
            # returned columns can be non-consecutive (A, C when B is hidden),
            # so col±1 would split visually adjacent data into two components.
            horizontal_cols = adjacent_cols.get(col, set()) if adjacent_cols else {col - 1, col + 1}
            neighbors.extend((row, neighbor_col) for neighbor_col in horizontal_cols)
            for neighbor in neighbors:
                if neighbor in remaining:
                    remaining.remove(neighbor)
                    queue.append(neighbor)
                    cells.append(neighbor)
        rows = [cell[0] for cell in cells]
        cols = [cell[1] for cell in cells]
        components.append(
            Component(
                RangeBounds(min(rows), min(cols), max(rows), max(cols)),
                len(cells),
            )
        )
    return components


def _box_gap_mergeable(a: RangeBounds, b: RangeBounds, gap_rows: int, gap_cols: int) -> bool:
    cols_overlap = not (a.end_col < b.start_col or b.end_col < a.start_col)
    rows_overlap = not (a.end_row < b.start_row or b.end_row < a.start_row)
    vertical_gap = max(b.start_row - a.end_row - 1, a.start_row - b.end_row - 1, 0)
    horizontal_gap = max(b.start_col - a.end_col - 1, a.start_col - b.end_col - 1, 0)
    return (cols_overlap and vertical_gap <= gap_rows) or (
        rows_overlap and horizontal_gap <= gap_cols
    )


def merge_components(
    components: list[Component], *, gap_rows: int = 1, gap_cols: int = 0
) -> list[Component]:
    merged = components[:]
    changed = True
    while changed:
        changed = False
        next_components: list[Component] = []
        used = [False] * len(merged)
        for i, comp in enumerate(merged):
            if used[i]:
                continue
            current = Component(comp.bounds, comp.occupied_count)
            used[i] = True
            for j in range(i + 1, len(merged)):
                if used[j]:
                    continue
                other = merged[j]
                if _box_gap_mergeable(current.bounds, other.bounds, gap_rows, gap_cols):
                    current = Component(
                        range_union(current.bounds, other.bounds),
                        current.occupied_count + other.occupied_count,
                    )
                    used[j] = True
                    changed = True
            next_components.append(current)
        merged = next_components
    return merged


def _row_values(grid: CsvGrid, bounds: RangeBounds, row_num: int) -> list[str]:
    if row_num not in grid.row_numbers:
        return []
    row = grid.values[grid.row_numbers.index(row_num)]
    values = []
    for col_idx, col_letter in enumerate(grid.col_letters):
        col_num = col_to_index(col_letter)
        if bounds.start_col <= col_num <= bounds.end_col:
            values.append(row[col_idx] if col_idx < len(row) else "")
    return values


def header_candidates(grid: CsvGrid, bounds: RangeBounds) -> list[int]:
    candidates = []
    for row in range(bounds.start_row, min(bounds.end_row, bounds.start_row + 4) + 1):
        values = _row_values(grid, bounds, row)
        non_empty = [value for value in values if value.strip()]
        if len(non_empty) >= max(1, min(2, bounds.col_count)):
            candidates.append(row)
    return candidates


def kind_guess(bounds: RangeBounds, density: float) -> str:
    if bounds.row_count >= 3 and bounds.col_count >= 2 and density >= 0.25:
        return "data_table"
    if bounds.row_count <= 2 or bounds.col_count <= 1:
        return "note_or_label"
    if density < 0.25:
        return "sparse_block"
    return "summary_block"


def summarize_components(grid: CsvGrid, components: list[Component], min_cells: int) -> list[dict[str, Any]]:
    result = []
    for idx, comp in enumerate(
        sorted(components, key=lambda item: (item.bounds.start_row, item.bounds.start_col)),
        start=1,
    ):
        if comp.occupied_count < min_cells:
            continue
        area = comp.bounds.row_count * comp.bounds.col_count
        density = comp.occupied_count / area if area else 0
        samples = []
        for row in range(comp.bounds.start_row, min(comp.bounds.end_row, comp.bounds.start_row + 2) + 1):
            samples.append(_row_values(grid, comp.bounds, row))
        result.append(
            {
                "id": f"T{idx}",
                "range": format_range(
                    comp.bounds.start_row,
                    comp.bounds.start_col,
                    comp.bounds.end_row,
                    comp.bounds.end_col,
                ),
                "rows": comp.bounds.row_count,
                "cols": comp.bounds.col_count,
                "occupied_cells": comp.occupied_count,
                "density": round(density, 4),
                "header_candidates": header_candidates(grid, comp.bounds),
                "kind_guess": kind_guess(comp.bounds, density),
                "sample": samples,
            }
        )
    return result


def detect_subtables(args) -> tuple[dict[str, Any], list[str]]:
    warnings: list[str] = []
    workbook = envelope_data(
        run_sheets(
            "+workbook-info",
            url=args.url,
            spreadsheet_token=args.spreadsheet_token,
            timeout=args.timeout,
        )
    )
    sheet = resolve_target_sheets(
        workbook,
        sheet_id=args.sheet_id,
        sheet_name=args.sheet_name,
        require_one=True,
    )[0]
    sid = sheet_identifier(sheet)
    title = sheet_title(sheet)
    locator = sheet_locator(sheet)

    col_count = min(int(sheet.get("column_count") or args.max_scan_cols), args.max_scan_cols)
    row_count = min(int(sheet.get("row_count") or args.max_scan_rows), args.max_scan_rows)
    scan_range = args.range or f"A1:{index_to_col(max(1, col_count))}{max(1, row_count)}"
    if not args.range:
        if int(sheet.get("column_count") or 0) > args.max_scan_cols:
            warnings.append(f"scan clipped to first {args.max_scan_cols} columns")
        if int(sheet.get("row_count") or 0) > args.max_scan_rows:
            warnings.append(f"scan clipped to first {args.max_scan_rows} rows")

    layout = envelope_data(
        run_sheets(
            "+sheet-info",
            url=args.url,
            spreadsheet_token=args.spreadsheet_token,
            **locator,
            flags={"include": "merges,hidden_rows,hidden_cols"},
            timeout=args.timeout,
        )
    )
    csv_data = envelope_data(
        run_sheets(
            "+csv-get",
            url=args.url,
            spreadsheet_token=args.spreadsheet_token,
            **locator,
            flags={
                "range": scan_range,
                "max_chars": args.max_chars,
                "skip_hidden": True if args.skip_hidden else None,
            },
            timeout=args.timeout,
        )
    )
    actual_range = str(csv_data.get("actual_range") or scan_range)
    if csv_data.get("has_more"):
        raise LarkCliError(
            f"+csv-get truncated the scan range at {actual_range}; narrow --range before detecting subtables"
        )

    grid = parse_annotated_csv(
        csv_data.get("annotated_csv", ""),
        csv_data.get("col_indices"),
        csv_data.get("row_indices"),
        actual_range,
    )
    if grid.row_numbers_inferred:
        warnings.append("CSV row numbers were inferred from the requested range")
    hidden_rows_raw = layout.get("hidden_rows") or []
    hidden_row_indexes = {
        int(value) + 1
        for value in hidden_rows_raw
        if isinstance(value, (int, str)) and str(value).isdigit()
    }
    hidden_columns_raw = layout.get("hidden_cols") or layout.get("hidden_columns") or []
    hidden_col_letters = set()
    for value in hidden_columns_raw if isinstance(hidden_columns_raw, list) else []:
        if isinstance(value, str) and value.isalpha():
            hidden_col_letters.add(value.upper())
        elif isinstance(value, (int, str)) and str(value).isdigit():
            hidden_col_letters.add(index_to_col(int(value) + 1))
    hidden_rows = sorted(row for row in grid.row_numbers if row in hidden_row_indexes)
    hidden_columns = [col for col in grid.col_letters if col.upper() in hidden_col_letters]
    if hidden_rows or hidden_columns:
        warnings.append("scan includes hidden rows or columns; pass --skip-hidden to exclude them")
    confirmed_external_merges = set()
    external_merge_anchors = list(_external_merge_anchors(grid, layout).items())
    if len(external_merge_anchors) > MAX_EXTERNAL_MERGE_ANCHOR_CHECKS:
        warnings.append(
            f"skipped confirmation for {len(external_merge_anchors) - MAX_EXTERNAL_MERGE_ANCHOR_CHECKS} "
            f"external merge anchors (limit: {MAX_EXTERNAL_MERGE_ANCHOR_CHECKS})"
        )
    for merge_ref, anchor in external_merge_anchors[:MAX_EXTERNAL_MERGE_ANCHOR_CHECKS]:
        try:
            anchor_data = envelope_data(
                run_sheets(
                    "+csv-get",
                    url=args.url,
                    spreadsheet_token=args.spreadsheet_token,
                    **locator,
                    flags={
                        "range": anchor,
                        "max_chars": 1024,
                        "skip_hidden": True if args.skip_hidden else None,
                    },
                    timeout=args.timeout,
                )
            )
            anchor_grid = parse_annotated_csv(
                anchor_data.get("annotated_csv", ""),
                anchor_data.get("col_indices"),
                anchor_data.get("row_indices"),
                anchor,
            )
            if _has_value(anchor_grid):
                confirmed_external_merges.add(merge_ref)
        except (LarkCliError, ValueError) as exc:
            warnings.append(f"could not confirm merge anchor {anchor}: {exc}")
    occupied = build_occupancy(
        grid,
        layout,
        confirmed_external_merges=confirmed_external_merges,
    )
    adjacent_rows = None
    adjacent_cols = None
    if args.skip_hidden:
        adjacent_rows = {}
        for previous, current in zip(grid.row_numbers, grid.row_numbers[1:]):
            adjacent_rows.setdefault(previous, set()).add(current)
            adjacent_rows.setdefault(current, set()).add(previous)
        col_numbers = [col_to_index(col) for col in grid.col_letters]
        adjacent_cols = {}
        for previous, current in zip(col_numbers, col_numbers[1:]):
            adjacent_cols.setdefault(previous, set()).add(current)
            adjacent_cols.setdefault(current, set()).add(previous)
    raw_components = _raw_components(
        occupied,
        adjacent_rows=adjacent_rows,
        adjacent_cols=adjacent_cols,
    )
    if len(raw_components) > args.max_merge_components:
        warnings.append(
            f"skipped gap-based component merging for {len(raw_components)} components "
            f"(limit: {args.max_merge_components})"
        )
        components = raw_components
    else:
        components = merge_components(
            raw_components,
            gap_rows=args.gap_rows,
            gap_cols=args.gap_cols,
        )
    subtables = summarize_components(grid, components, args.min_cells)
    return {
        "sheet_id": sid,
        "sheet": title,
        "scan_range": scan_range,
        "actual_range": actual_range,
        "visibility": {
            "skip_hidden": args.skip_hidden,
            "hidden_rows_in_range": hidden_rows,
            "hidden_columns_in_range": hidden_columns,
        },
        "subtables": subtables,
    }, warnings


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    add_spreadsheet_args(parser, require_sheet=True, allow_sheet=True)
    parser.add_argument("--range")
    parser.add_argument("--max-scan-rows", type=int, default=5000)
    parser.add_argument("--max-scan-cols", type=int, default=200)
    parser.add_argument("--gap-rows", type=int, default=1)
    parser.add_argument("--gap-cols", type=int, default=0)
    parser.add_argument("--min-cells", type=int, default=2)
    parser.add_argument("--max-merge-components", type=int, default=2000)
    parser.add_argument("--max-chars", type=int, default=25000)
    parser.add_argument("--skip-hidden", action="store_true")
    parser.add_argument("--timeout", type=int, default=60)
    args = parser.parse_args()
    try:
        data, warnings = detect_subtables(args)
    except (LarkCliError, ValueError, TypeError) as exc:
        emit_error(ACTION, str(exc))
    emit_success(ACTION, data, warnings)


if __name__ == "__main__":
    main()

