        // bitmap; anchor it under the cursor at the grab point (no jump).
        try {
          const g = this._makeDragGhost(entry);
          if (g) {
            const r = frame.getBoundingClientRect();
            const gx = g.pad + Math.max(0, Math.min(g.w, e.clientX - r.left));
