        this._dragFrom = null;
        if (this._dragGhost) { this._dragGhost.remove(); this._dragGhost = null; }
      });
      thumb.addEventListener('dragover', (e) => {
        if (this._dragFrom == null) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
